import React, { useState } from 'react';
import { Package, TrendingUp, Star, Zap, ChevronRight } from 'lucide-react';

const TopProducts = () => {
  const [selectedFilter, setSelectedFilter] = useState('Tous');

  const topProducts = [
    { 
      name: 'Casque Premium', 
      sales: 342, 
      revenue: '$12,450', 
      stock: 45,
      category: 'Audio',
      rating: 4.8,
      trend: 'up'
    },
    { 
      name: 'Souris sans fil', 
      sales: 289, 
      revenue: '$8,670', 
      stock: 12,
      category: 'Périphériques',
      rating: 4.5,
      trend: 'up'
    },
    { 
      name: 'Support portable', 
      sales: 156, 
      revenue: '$5,460', 
      stock: 23,
      category: 'Accessoires',
      rating: 4.2,
      trend: 'stable'
    },
    { 
      name: 'Clavier mécanique', 
      sales: 234, 
      revenue: '$9,360', 
      stock: 8,
      category: 'Périphériques',
      rating: 4.7,
      trend: 'up'
    },
    { 
      name: 'Webcam HD', 
      sales: 187, 
      revenue: '$6,545', 
      stock: 15,
      category: 'Vidéo',
      rating: 4.4,
      trend: 'stable'
    },
  ];

  const filters = ['Tous', 'Audio', 'Périphériques', 'Accessoires', 'Vidéo'];

  const getTrendColor = (trend) => {
    switch(trend) {
      case 'up': return 'text-accent-500 bg-accent-50 dark:bg-accent-900/20';
      case 'down': return 'text-red-500 bg-red-50 dark:bg-red-900/20';
      default: return 'text-neutral-500 bg-neutral-50 dark:bg-neutral-800';
    }
  };

  const getTrendIcon = (trend) => {
    switch(trend) {
      case 'up': return <TrendingUp className="h-3 w-3" />;
      case 'down': return <TrendingUp className="h-3 w-3 rotate-180" />;
      default: return <div className="h-3 w-3 rounded-full bg-neutral-400" />;
    }
  };

  const filteredProducts = selectedFilter === 'Tous' 
    ? topProducts 
    : topProducts.filter(product => product.category === selectedFilter);

  return (
    <div className="bg-gradient-to-br from-white to-white/70 dark:from-neutral-900 dark:to-neutral-900/70 backdrop-blur-xl rounded-2xl p-6 shadow-lg border border-white/30 dark:border-neutral-800/50 hover:shadow-xl transition-all duration-300 animate-slide-up">
      {/* En-tête */}
      <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-6">
        <div>
          <h3 className="text-lg sm:text-xl font-bold text-neutral-900 dark:text-white mb-1">
            Produits populaires
          </h3>
          <p className="text-sm text-neutral-600 dark:text-neutral-400">
            Produits les plus vendus cette semaine
          </p>
        </div>

        {/* Filtres */}
        <div className="flex flex-wrap gap-2">
          {filters.map((filter) => (
            <button
              key={filter}
              onClick={() => setSelectedFilter(filter)}
              className={`px-3 py-1.5 text-sm rounded-lg transition-all duration-300 ${
                selectedFilter === filter
                  ? 'bg-primary-500 text-white shadow-sm'
                  : 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 hover:bg-neutral-200 dark:hover:bg-neutral-700'
              }`}
            >
              {filter}
            </button>
          ))}
        </div>
      </div>

      {/* Liste des produits */}
      <div className="space-y-3">
        {filteredProducts.map((product, index) => (
          <div 
            key={index}
            className="group flex items-center justify-between p-4 rounded-xl hover:bg-neutral-50 dark:hover:bg-neutral-800/50 transition-all duration-300 hover:translate-x-2 cursor-pointer border border-transparent hover:border-primary-200 dark:hover:border-primary-800/30"
          >
            <div className="flex items-center space-x-4">
              {/* Numéro de rang */}
              <div className={`flex-shrink-0 w-8 h-8 rounded-lg flex items-center justify-center font-bold text-sm ${
                index === 0 
                  ? 'bg-yellow-100 dark:bg-yellow-900/30 text-yellow-600 dark:text-yellow-400' 
                  : index === 1 
                  ? 'bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400'
                  : 'bg-primary-100 dark:bg-primary-900/30 text-primary-600 dark:text-primary-400'
              }`}>
                #{index + 1}
              </div>

              {/* Icône du produit */}
              <div className="relative">
                <div className="h-12 w-12 rounded-xl bg-gradient-to-r from-primary-500/10 to-secondary-500/10 flex items-center justify-center group-hover:scale-110 transition-transform duration-300">
                  <Package className="h-6 w-6 text-primary-500" />
                </div>
                <div className={`absolute -top-1 -right-1 w-5 h-5 rounded-full ${getTrendColor(product.trend)} flex items-center justify-center`}>
                  {getTrendIcon(product.trend)}
                </div>
              </div>

              {/* Infos produit */}
              <div className="min-w-0">
                <div className="flex items-center gap-2 mb-1">
                  <h4 className="font-semibold text-neutral-900 dark:text-white truncate group-hover:text-primary-600 dark:group-hover:text-primary-400 transition-colors">
                    {product.name}
                  </h4>
                  <span className="text-xs px-2 py-0.5 bg-neutral-100 dark:bg-neutral-800 text-neutral-600 dark:text-neutral-400 rounded-full">
                    {product.category}
                  </span>
                </div>

                <div className="flex items-center gap-4">
                  <div className="flex items-center gap-1">
                    <Star className="h-3 w-3 text-yellow-500 fill-yellow-500" />
                    <span className="text-xs text-neutral-600 dark:text-neutral-400">
                      {product.rating}
                    </span>
                  </div>

                  <div className="flex items-center gap-1">
                    <Zap className="h-3 w-3 text-accent-500" />
                    <span className="text-xs text-neutral-600 dark:text-neutral-400">
                      {product.sales} ventes
                    </span>
                  </div>
                </div>
              </div>
            </div>

            {/* Stats côté droit */}
            <div className="flex items-center gap-6">
              <div className="text-right">
                <p className="font-bold text-lg text-neutral-900 dark:text-white">
                  {product.revenue}
                </p>
                <p className={`text-xs font-medium ${
                  product.stock < 10 
                    ? 'text-red-500 animate-pulse' 
                    : product.stock < 20 
                    ? 'text-warning-500' 
                    : 'text-accent-500'
                }`}>
                  {product.stock} en stock
                </p>
              </div>

              <ChevronRight className="h-5 w-5 text-neutral-400 group-hover:text-primary-500 group-hover:translate-x-1 transition-all duration-300" />
            </div>
          </div>
        ))}
      </div>

      {/* Pied de section */}
      <div className="mt-6 pt-6 border-t border-neutral-200 dark:border-neutral-700">
        <div className="flex items-center justify-between">
          <div className="text-sm text-neutral-600 dark:text-neutral-400">
            Total: {filteredProducts.length} produits affichés
          </div>
          <button className="text-sm font-medium text-primary-600 dark:text-primary-400 hover:text-primary-700 dark:hover:text-primary-300 flex items-center gap-1 transition-colors group">
            Voir tous les produits
            <ChevronRight className="h-4 w-4 group-hover:translate-x-1 transition-transform" />
          </button>
        </div>
      </div>
    </div>
  );
};

export default TopProducts;
